function checkLayers(result, gold) {
  const issues = [];
  for (const [layer, exp] of Object.entries(gold.expect)) {
    const got = result[layer] || {};
    for (const [k, v] of Object.entries(exp)) if (got[k] !== v) issues.push(layer + '.' + k);
  }
  return { pass: issues.length === 0, issues };
}
const gold = { expect: { api: { status: 200 }, stream: { resumed: true }, ui: { citations: 2 } } };
const good = { api: { status: 200 }, stream: { resumed: true }, ui: { citations: 2 } };
const bad = { api: { status: 200 }, stream: { resumed: false }, ui: { citations: 2 } };
console.log(JSON.stringify(checkLayers(good, gold)));
console.log(JSON.stringify(checkLayers(bad, gold)));

